 String webThemeScript(){return "(function(){const accent="+JSONObject.quote(hex(green))+",light="+JSONObject.quote(hex(blend(green,surface,.85f)))+",ink="+JSONObject.quote(hex(dark))+",surface="+JSONObject.quote(hex(surface))+",link="+JSONObject.quote(hex(accentText))+",night="+night+";const keys=['color','background-color','border-top-color','border-right-color','border-bottom-color','border-left-color'];for(const e of document.querySelectorAll('body *')){if(e.closest('script,style,iframe,svg,.abon-current-tile,.abon-photo-picker,.abon-photo-name,.abon-photo-native-wrap'))continue;for(const k of keys){let mark='data-abon-tone-'+k, orig='data-abon-original-'+k,pri='data-abon-priority-'+k;if(e.hasAttribute(orig)){let val=e.getAttribute(orig);if(val)e.style.setProperty(k,val,e.getAttribute(pri)||'');else e.style.removeProperty(k);}let tone=e.getAttribute(mark);if(!tone){let m=getComputedStyle(e).getPropertyValue(k).match(/^rgba?\\(\\s*(\\d+),\\s*(\\d+),\\s*(\\d+)(?:,\\s*([\\d.]+))?\\)$/);if(!m||m[4]==='0')continue;let r=+m[1],g=+m[2],b=+m[3],lo=Math.min(r,g,b),hi=Math.max(r,g,b);if(g-r>=9&&g-b>=6)tone=lo>170?'light':'accent';else if(k==='background-color'&&lo>205)tone='surface';else if(k==='color'&&hi<160&&hi-lo<65)tone='ink';else continue;e.setAttribute(mark,tone);e.setAttribute(orig,e.style.getPropertyValue(k));e.setAttribute(pri,e.style.getPropertyPriority(k));}if(tone==='accent')e.style.setProperty(k,k==='color'?link:accent,'important');else if(tone==='light')e.style.setProperty(k,light,'important');else if(night)e.style.setProperty(k,tone==='surface'?surface:ink,'important');}}for(const e of document.querySelectorAll('.abon-difference'))e.style.setProperty('color',link,'important');})()";}
